def ajouter_le_module_cantine(apps, schema_editor):
    """
    Nouveau module « Cantine » : les établissements déjà créés n'ont aucune ligne pour lui (une absence de ligne vaut refus). Chaque rôle
    en reçoit une, refusée sauf pour le super administrateur ; le développeur l'accorde ensuite au gérant de la cantine (rôle « Personnel »)
    depuis la matrice de permissions. Un établissement créé après cette migration l'obtient par PermissionMatrix.seed_pour().
    """
    from permissions_matrix.matrice_par_defaut import MATRICE_PAR_DEFAUT

    PermissionMatrix = apps.get_model("permissions_matrix", "PermissionMatrix")
    Etablissement = apps.get_model("etablissement", "Etablissement")
    roles = [role.value for role in MATRICE_PAR_DEFAUT]
    cibles = [None, *Etablissement.objects.all()]  # None : les éventuelles lignes historiques d'avant le multi-établissement
    PermissionMatrix.objects.bulk_create(
        [
            PermissionMatrix(etablissement=cible, role=role, module="cantine", autorise=(role == "super_administrateur"))
            for cible in cibles for role in roles
        ],
        ignore_conflicts=True,
    )


